def transpose_two_strings(arr):
    str1, str2 = arr
    max_length = max(len(str1), len(str2))
    result = []
    for i in range(max_length):
        char1 = str1[i] if i < len(str1) else ' '
        char2 = str2[i] if i < len(str2) else ' '
        result.append(f"{char1} {char2}")
    return '\n'.join(result)
